from shelf import books, export


def setup_function():
    books.clear()


def test_export_csv_empty_shelf_is_header_only():
    assert export.export_csv() == "title,author\n"


def test_export_csv_lists_every_book():
    books.add("Dune", "Frank Herbert")
    books.add("Emma", "Jane Austen")
    assert export.export_csv() == (
        "title,author\n"
        "Dune,Frank Herbert\n"
        "Emma,Jane Austen\n"
    )


def test_export_csv_quotes_commas():
    books.add("Good Omens", "Pratchett, Gaiman")
    assert export.export_csv() == 'title,author\nGood Omens,"Pratchett, Gaiman"\n'

